int process_magic_device_event(struct hid_device *hdev, struct hid_report *report, u8 *data, int size) {
    struct magic_drvdata *drvdata = hid_get_drvdata(hdev);
    int report_id = data[0];

    switch (report_id) {
    case TRACKPAD_REPORT_ID: {
        if (size < 4) return 0;
        int touch_count = data[1];
        if (touch_count > MAX_TOUCHES) touch_count = MAX_TOUCHES;

        for (int i = 0; i < touch_count; i++) {
            int idx = 2 + i * 6;
            if (idx + 5 >= size) return 0;

            int x = (data[idx] << 8) | data[idx + 1];
            int y = (data[idx + 2] << 8) | data[idx + 3];
            int pressure = (data[idx + 4] << 8) | data[idx + 5];
            input_report_abs(drvdata->input, ABS_MT_POSITION_X, x);
            input_report_abs(drvdata->input, ABS_MT_POSITION_Y, y);
            input_report_abs(drvdata->input, ABS_MT_PRESSURE, pressure);
            input_mt_sync(drvdata->input);
        }
        break;
    }

    case MOUSE_REPORT_ID: {
        if (size < 5) return 0;
        int dx = data[1];
        int dy = data[2];
        int scroll = data[3];
        int buttons = data[4];

        input_report_rel(drvdata->input, REL_X, dx);
        input_report_rel(drvdata->input, REL_Y, dy);
        input_report_rel(drvdata->input, REL_WHEEL, scroll);
        input_report_key(drvdata->input, BTN_LEFT, buttons & 1);
        input_report_key(drvdata->input, BTN_RIGHT, buttons & 2);
        break;
    }

    case DOUBLE_REPORT_ID: {
        // Handle double report (trackpad + mouse) if necessary
        if (size < 10) return 0;
        // Example: first part is touch data, second part is mouse
        // This is a placeholder for more complex handling
        break;
    }

    default:
        return 0;
    }

    input_sync(drvdata->input);
    return 1;
}

int process_magic_input_event(struct hid_device *hdev, struct hid_report *report, u8 *data, int size)
{
    struct magic_drvdata *drvdata = hid_get_drvdata(hdev);
    int ret = 0;

    if (!drvdata)
        return 0;

    switch (report->id) {
    case TRACKPAD_REPORT_ID:
        if (size < TRACKPAD_MIN_SIZE)
            break;

        ret = process_trackpad_report(hdev, data, size);
        break;

    case MOUSE_REPORT_ID:
        if (size < MOUSE_MIN_SIZE)
            break;

        ret = process_mouse_report(hdev, data, size);
        break;

    case DOUBLE_REPORT_ID:
        if (size < DOUBLE_MIN_SIZE)
            break;

        ret = process_double_report(hdev, data, size);
        break;

    default:
        break;
    }

    if (ret)
        input_sync(drvdata->input);

    return ret ? 1 : 0;
}

